export default async (): Promise<RequestMessage> => (
{
  // gv.invoke runs another SAVED request through the whole pipeline and
  // resolves its response. The path is display names joined by "/", it is typed
  // (it completes inside the quotes, and `body` is the response message), and
  // the second argument arrives as the target's gv.request.params.
  collection: (await gv.invoke("Collections/ListCollections", { refresh: false }))
    .body.collections.find((c: { id: string }) => c.id === "example").id,

  // Describe a method that came from the OTHER source kind: echo.v1 is built by
  // bazel from //proto/echo/v1:echov1_proto, not reflected off a server.
  service: "echo.v1.EchoService",
  method: "ServerStream",
}
)
